-- New templates, tenant change allowance and approval requests (Master DB). Additive and idempotent; normal backend startup runs the same steps.
-- Run after 05 as the knockout_master owner (the application role). Existing assignments are not touched.
BEGIN;
SET LOCAL lock_timeout = '5s';
SELECT pg_advisory_xact_lock(742918);
SET LOCAL search_path TO knockout_master, pg_catalog;
CREATE TABLE IF NOT EXISTS template_change_requests (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,company_id BIGINT NULL REFERENCES companies(id) ON DELETE SET NULL,company_name VARCHAR(160) NOT NULL,current_template_id BIGINT NOT NULL REFERENCES ui_templates(id),requested_template_id BIGINT NOT NULL REFERENCES ui_templates(id),reason VARCHAR(500) NOT NULL,status VARCHAR(10) NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','approved','rejected')),requested_by BIGINT NOT NULL,requested_by_name VARCHAR(120) NOT NULL,reviewed_by BIGINT NULL,reviewed_by_name VARCHAR(120) NULL,review_note VARCHAR(500) NOT NULL DEFAULT '',reviewed_at TIMESTAMP WITH TIME ZONE NULL,admin_seen_at TIMESTAMP WITH TIME ZONE NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,CHECK ((status='pending')=(reviewed_at IS NULL)));
CREATE TABLE IF NOT EXISTS template_allowance_resets (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,company_id BIGINT NULL REFERENCES companies(id) ON DELETE SET NULL,company_name VARCHAR(160) NOT NULL,previous_count INTEGER NOT NULL,reset_by BIGINT NOT NULL,reset_by_name VARCHAR(120) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT INTO ui_templates (code,name,preview) VALUES
  ('midnight-dark','Midnight Dark','{"description":"Charcoal surfaces with warm gold, serif headings and an editorial dashboard.","layout":"sidebar","colors":["#0E0F11","#D4B06A","#17191C","#212429"]}'::jsonb),
  ('ocean-dark','Ocean Dark','{"description":"Deep navy with bright cyan, an icon rail and a tiled dashboard.","layout":"rail","colors":["#061423","#3FD0E6","#0A1C30","#122943"]}'::jsonb),
  ('emerald','Emerald','{"description":"Dark green masthead over warm ivory with classic serif headings.","layout":"masthead","colors":["#0F3B2E","#B9975B","#FAF7EE","#FFFFFF"]}'::jsonb),
  ('amoled','AMOLED','{"description":"Pure black, hairline borders and one quiet accent. Work comes first.","layout":"text","colors":["#FFFFFF","#6BE3A4","#000000","#0B0B0B"]}'::jsonb),
  ('modern-light','Modern Light','{"description":"Clean neutral workspace with a light sidebar and a two-column dashboard.","layout":"split","colors":["#27272A","#A1A1AA","#F7F7F8","#FFFFFF"]}'::jsonb)
ON CONFLICT (code) DO NOTHING;
ALTER TABLE companies ADD COLUMN IF NOT EXISTS template_change_count INTEGER NOT NULL DEFAULT 0 CHECK (template_change_count >= 0);
ALTER TABLE template_assignments ADD COLUMN IF NOT EXISTS source VARCHAR(12) NOT NULL DEFAULT 'superadmin' CHECK (source IN ('superadmin','admin','request')), ADD COLUMN IF NOT EXISTS request_id BIGINT NULL REFERENCES template_change_requests(id);
CREATE UNIQUE INDEX IF NOT EXISTS template_request_one_pending ON template_change_requests (company_id) WHERE status='pending';
CREATE INDEX IF NOT EXISTS template_request_history ON template_change_requests (company_id,id);
COMMIT;
